'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const dash = fs.readFileSync('src/marketing/pages/MarketingDashboardPage.tsx','utf8');
const plan = fs.readFileSync('src/marketing/workflow/PlanDetail.tsx','utf8');
const prep = fs.readFileSync('src/marketing/workflow/PublishPage.tsx','utf8');
const task = fs.readFileSync('src/marketing/workflow/TaskDetail.tsx','utf8');
const server = fs.readFileSync('server/marketing/workflow.ts','utf8');
const schema = fs.readFileSync('server/_marketing-workflow-schema.ts','utf8');
assert.match(dash, /mkw-dashboard-plan[^\n]*key=\{id\}>/);
assert.doesNotMatch(dash, /key=\{id\} open=\{lines\.length/);
assert.match(dash, /<CalendarBlank size=\{17\}\/>التقرير/);
assert.match(dash, />فتح<\/button><\/td>/);
assert.doesNotMatch(task, /mkw-executor-copy/);
assert.match(prep, /saveManualPostLink/);
assert.match(prep, /workPost\('save_plan_post_url', \{ lineId: data.line.id, url: postUrl.trim\(\), publishedOn \}\)/);
assert.match(plan, /plan!\.created_at/);
assert.match(plan, /mkw-plan-history[^>]*open=/);
assert.match(dash, /نشر في الموعد/);
assert.match(dash, /تأخر في النشر/);
assert.match(server, /manual_published_on=\$\{url \? publishedOn : null\}::date/);
assert.match(server, /if \(url && !isWorkDate\(publishedOn\)\)/);
assert.match(schema, /MARKETING_WORKFLOW_MANUAL_PUBLISHED_DATE_SQL/);
assert.match(schema, /values\('schema-14'\)/);
assert.doesNotMatch(schema.slice(schema.indexOf('export const MARKETING_WORKFLOW_MANUAL_PUBLISHED_DATE_SQL'),schema.indexOf('export const MARKETING_WORKFLOW_TERMINAL_REJECTION_SQL')),/\bdrop\s+table\b|\btruncate\b/i);
console.log('PASS 15/15 marketing manual publishing, review history, report and safe migration checks');
